mapper.select:
SELECT * FROM operation_logs

    is_deleted = 0

        AND user_id = #{params.userId}


        AND username LIKE CONCAT('%', #{params.username}, '%')


        AND operation_type = #{params.operationType}


        AND module = #{params.module}


        AND target_id = #{params.targetId}


        AND operation_result = #{params.operationResult}


        AND severity_level = #{params.severityLevel}


        AND is_sensitive = #{params.isSensitive}


        AND related_operation_id = #{params.relatedOperationId}


        AND created_at >= #{params.startTime}


        AND created_at <= #{params.endTime}


ORDER BY created_at DESC

SELECT * FROM operation_logs
WHERE is_deleted = 0 AND related_operation_id = #{relatedOperationId}
ORDER BY created_at ASC

SELECT * FROM operation_logs
WHERE is_deleted = 0 AND module = #{module} AND target_id = #{targetId}
ORDER BY created_at DESC

SELECT * FROM operation_logs
WHERE is_deleted = 0 AND created_at BETWEEN #{startTime} AND #{endTime}
ORDER BY created_at DESC

SELECT COUNT(*) AS total_count, COUNT(DISTINCT module) AS module_count, COUNT(DISTINCT operation_type) AS operation_type_count, SUM(CASE WHEN operation_result = '成功' THEN 1 ELSE 0 END) AS success_count, SUM(CASE WHEN operation_result = '失败' THEN 1 ELSE 0 END) AS fail_count, SUM(CASE WHEN is_sensitive = 1 THEN 1 ELSE 0 END) AS sensitive_count, MAX(created_at) AS last_operation_time FROM operation_logs WHERE is_deleted = 0 AND user_id = #{userId}
AND created_at >= #{startTime}
AND created_at <= #{endTime}

SELECT module, operation_type, COUNT(DISTINCT user_id) AS user_count, COUNT(*) AS operation_count, SUM(CASE WHEN operation_result = '成功' THEN 1 ELSE 0 END) AS success_count, SUM(CASE WHEN operation_result = '失败' THEN 1 ELSE 0 END) AS fail_count FROM operation_logs WHERE is_deleted = 0
AND module IN
#{module}
AND created_at >= #{startTime}
AND created_at <= #{endTime}
GROUP BY module, operation_type ORDER BY operation_count DESC

SELECT operation_type, module, COUNT(DISTINCT user_id) AS user_count, COUNT(*) AS operation_count, SUM(CASE WHEN operation_result = '成功' THEN 1 ELSE 0 END) AS success_count, SUM(CASE WHEN operation_result = '失败' THEN 1 ELSE 0 END) AS fail_count FROM operation_logs WHERE is_deleted = 0
AND operation_type IN
#{type}
AND created_at >= #{startTime}
AND created_at <= #{endTime}
GROUP BY operation_type, module ORDER BY operation_count DESC

SELECT *
FROM operation_logs
WHERE is_deleted = 0 AND user_id = #{userId}
AND created_at BETWEEN #{startTime} AND #{endTime}
AND (
    SELECT COUNT(*)
    FROM operation_logs as inner_logs
    WHERE inner_logs.user_id = operation_logs.user_id
    AND inner_logs.created_at BETWEEN DATE_ADD(operation_logs.created_at, INTERVAL -1 MINUTE)
    AND operation_logs.created_at
) > #{threshold}
ORDER BY created_at DESC
